public static METCCRController construct(Args _args)
{
    METCCRController controller = new METCCRController();
    controller.parmArgs(_args);
    controller.parmReportName(ssrsReportStr(METCCRReport,Report));
    controller.parmShowDialog(false);
    controller.startOperation();

    return controller;
}

